-- DropBlox becomes Fruit Drop: falling fruit pieces, match 3 to pop, full rows clear, chains and special fruit, 12 goal levels and Endless.
-- The id (game-drop-blox), slug and page address stay the same, so existing links keep working.
-- Run once in the Supabase SQL Editor (safe to run again).
update games set data = data || $j${"title": "Fruit Drop", "summary": "Drop fruit, match 3, and set off juicy chains!", "rules": ["Fruit falls into the well in pieces of 2, 3 or 4.", "Move it with the arrows, turn it with Up or Z, and drop it with Space. On a phone, use the big buttons or swipe.", "Each fruit falls on its own until it lands on something.", "Line up 3 or more of the same fruit, across or up and down, and they pop.", "Fill a whole row with any fruit and it clears too.", "When fruit falls into a new match by itself, that's a chain, and each chain scores more.", "Match 4 in a line for a striped fruit: pop it to clear its whole row or column.", "Match 5 in an L or T for a wrapped fruit: pop it to blast the fruit all around it.", "Match 5 in a straight line for a golden star: drop any fruit on it and every fruit of that kind pops.", "Each level has a goal. Finish it for 1 to 3 stars and the next level opens.", "Sound is on: press the speaker button to turn it off."], "vocabExample": "In Fruit Drop, spot a pattern in the fruit, then line up three of a kind to pop them."}$j$::jsonb
  || jsonb_build_object('cover', (data->'cover') || jsonb_build_object('alt', $a$Fruit Drop's glossy well of drawn fruit mid-chain: a striped orange zaps its row, a wrapped blueberry bursts in a pink blast, and "Juicy! Chain ×3" flashes while Chike points and cheers$a$::text)),
  updated_at = now()
where id = 'game-drop-blox';
